	@ParameterizedTest
	@CsvSource({ "false,128", "true,128", "false,65536", "true,65536" })
	void closeDuringCallerCaptureOrMemoValidationRejectsLateResult(boolean memoized, int capacity,
			@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, false, capacity)) {
			IRI expected = VF.createIRI("urn:snapshot-cache:close-race");
			long id = fixture.store(expected);
			try (View view = fixture.openView(); ExecutorService executor = Executors.newSingleThreadExecutor()) {
				AtomicBoolean blocked = new AtomicBoolean();
				CountDownLatch entered = new CountDownLatch(1);
				CountDownLatch released = new CountDownLatch(1);
				IRI input = new AbstractIRI() {
					private void awaitRelease() {
						assertFalse(Thread.holdsLock(view.snapshot.txnRef()),
								"Caller capture and memo validation must remain outside the native monitor");
						if (blocked.get()) {
							entered.countDown();
							try {
								assertTrue(released.await(10, TimeUnit.SECONDS));
							} catch (InterruptedException failure) {
								Thread.currentThread().interrupt();
								throw new AssertionError(failure);
							}
						}
					}

					@Override
					public String getNamespace() {
						awaitRelease();
						return expected.getNamespace();
					}

					@Override
					public String getLocalName() {
						return expected.getLocalName();
					}

					@Override
					public String stringValue() {
						awaitRelease();
						return expected.stringValue();
					}
				};
				if (memoized) {
					assertEquals(id, fixture.values.getId(view.snapshot, input));
				}
				blocked.set(true);
				Future<?> late = executor.submit(() -> assertThrows(IOException.class,
						() -> fixture.values.getId(view.snapshot, input)));
				try {
					assertTrue(entered.await(10, TimeUnit.SECONDS));
					view.close();
				} finally {
					released.countDown();
				}
				late.get(10, TimeUnit.SECONDS);
				assertThrows(IOException.class, () -> fixture.values.getId(view.snapshot, input));
			}
		}
	}

	private static Observed observe(LmdbValue ready, View view) {
		return observe(ready, view.snapshot);
	}

	private static Observed observe(LmdbValue ready, ValueStore.ReadSnapshot snapshot) {
		AtomicInteger calls = new AtomicInteger();
		AtomicInteger iriCalls = new AtomicInteger();
		LmdbValue observed = mock(ready.getClass(), withSettings().spiedInstance(ready).defaultAnswer(invocation -> {
			if (PAYLOAD_GETTERS.contains(invocation.getMethod().getName())) {
				assertFalse(Thread.holdsLock(snapshot.txnRef()), "Caller payload must stay outside the Txn monitor");
				calls.incrementAndGet();
				String getter = invocation.getMethod().getName();
				if (getter.equals("getNamespace") || getter.equals("getLocalName")) {
					iriCalls.incrementAndGet();
				}
			}
			return invocation.callRealMethod();
		}));
		assertEquals(ready.getClass(), observed.getClass(),
				"Existing inline Mockito must preserve built-in class identity");
		return new Observed(observed, calls, iriCalls);
	}

	private record Observed(LmdbValue value, AtomicInteger payloadCalls, AtomicInteger iriCaptureCalls) {
	}

